import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    static long power(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long n = Long.parseLong(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        List<long[]> factors = new ArrayList<>();
        long temp = n;
        for (long p = 2; p * p <= temp; p++) {
            if (temp % p == 0) {
                int c = 0;
                while (temp % p == 0) { temp /= p; c++; }
                factors.add(new long[]{p, c});
            }
        }
        if (temp > 1) factors.add(new long[]{temp, 1});

        long[] inv = new long[70];
        for (int i = 1; i < 70; i++) inv[i] = power(i, MOD - 2, MOD);

        long ans = 1;
        for (long[] f : factors) {
            long p = f[0];
            int e = (int) f[1];
            long[] dp = new long[e + 1];
            long cur = 1;
            for (int i = 0; i <= e; i++) {
                dp[i] = cur;
                cur = cur * (p % MOD) % MOD;
            }
            for (int t = 0; t < k; t++) {
                long[] nd = new long[e + 1];
                long pref = 0;
                for (int i = 0; i <= e; i++) {
                    pref = (pref + dp[i]) % MOD;
                    nd[i] = pref * inv[i + 1] % MOD;
                }
                dp = nd;
            }
            ans = ans * dp[e] % MOD;
        }

        System.out.println(ans);
    }
}
